-- Create "polls" table
CREATE TABLE `polls` (`id` int unsigned NOT NULL AUTO_INCREMENT, `description` text NULL, `max_answers` int NOT NULL DEFAULT 1, `available_from` datetime NULL, `available_to` datetime NULL, `results_only` bool NOT NULL DEFAULT false, `allow_revote` bool NOT NULL DEFAULT true, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `polls_nid` (`nid`), CONSTRAINT `polls_nodes_nodes` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "poll_options" table
CREATE TABLE `poll_options` (`id` int unsigned NOT NULL AUTO_INCREMENT, `label` varchar(500) NOT NULL, `weight` int NOT NULL DEFAULT 0, `poll_id` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `polloption_poll_id` (`poll_id`), CONSTRAINT `poll_options_polls_options` FOREIGN KEY (`poll_id`) REFERENCES `polls` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "poll_votes" table
CREATE TABLE `poll_votes` (`id` int unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime NOT NULL, `poll_id` int unsigned NOT NULL, `option_id` int unsigned NOT NULL, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `pollvote_poll_id_user_id_option_id` (`poll_id`, `user_id`, `option_id`), INDEX `pollvote_poll_id_user_id` (`poll_id`, `user_id`), INDEX `pollvote_option_id` (`option_id`), INDEX `pollvote_user_id` (`user_id`), CONSTRAINT `poll_votes_polls_votes` FOREIGN KEY (`poll_id`) REFERENCES `polls` (`id`) ON DELETE CASCADE, CONSTRAINT `poll_votes_poll_options_option_votes` FOREIGN KEY (`option_id`) REFERENCES `poll_options` (`id`) ON DELETE CASCADE, CONSTRAINT `poll_votes_users_poll_votes` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
